// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DnGmxBatchingManager} from "../src/DnGmxBatchingManager.sol";

contract InvMutTest is Test {
    DnGmxBatchingManager c;
    function setUp() public { c = new DnGmxBatchingManager(); }
    function testFuzz_property(address nonOwner, address newKeeper) public {
        vm.assume(nonOwner != c.owner());
        vm.assume(newKeeper != address(0));
        vm.prank(nonOwner);
        try c.setKeeper(newKeeper) {
            assertTrue(c.keeper() == newKeeper && nonOwner == c.owner());
        } catch {
            assertTrue(c.keeper() != newKeeper || nonOwner == c.owner());
        }
    }
}
